"""0.5.4 packaged-browser suite: the exact .pbiviz JS/CSS in opaque sandbox
iframes; only Power BI host services are simulated (Power BI-shaped: report
theme palette, SemanticFilter in objects.general.filter, JSON echo in
jsonFilters, wall-clock Date cells). Not a Power BI Desktop test.

Env: FF_TZ (default Europe/Amsterdam), FF_CHROMIUM, FF_HARNESS.
"""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json, os, re, datetime
ROOT = Path(__file__).resolve().parent.parent
VERSION = json.loads((ROOT / 'package.json').read_text())['version']
OUT = ROOT / f'docs/qa/{VERSION}'; OUT.mkdir(parents=True, exist_ok=True)
HTML = Path(os.environ.get('FF_HARNESS') or ROOT / f'preview/FieldFind_Search_Date_{VERSION}.html').read_text()
TZ = os.environ.get('FF_TZ', 'Europe/Amsterdam')
CHROMIUM = os.environ.get('FF_CHROMIUM') or ('/usr/bin/chromium' if Path('/usr/bin/chromium').exists() else None)
checks = []; errors = []; requests = []
def check(name, ok):
    if not ok: raise AssertionError(name)
    checks.append(name); print('PASS', name, flush=True)

MOHAMED = """(()=>{const c=(name,roles,type)=>({displayName:name,queryName:'Range.'+name,expr:{source:{entity:'Range'},ref:name},roles,type});
 ffTest.customColumns=[c('Article No',{recordKey:true,fields:true},{numeric:true,integer:true}),c('Article Name',{fields:true},{text:true}),c('RU EDS',{fields:true},{dateTime:true}),c('HFB',{fields:true,dates:true},{text:true})];
 ffTest.rawRows=[[60637328,'VINTERFINT candle',new Date(2027,0,1),'08'],[60637329,'VINTERFINT bauble',new Date(2027,0,1),'08'],[60637330,'STRÅLA lamp',new Date(2026,11,1),'10'],[60637331,'BILLY',new Date(2026,9,1),'02']];ffTest.send();})()"""

with sync_playwright() as p:
    browser = p.chromium.launch(executable_path=CHROMIUM, headless=True, args=['--no-sandbox', '--disable-dev-shm-usage'])
    page = None
    def setup(w=600, h=76, theme='default', js=''):
        global page
        if page: page.close()
        page = browser.new_page(viewport={'width': 1100, 'height': 700}, timezone_id=TZ)
        page.set_default_timeout(3500)
        # Fix the reference day, not timer flow: the original fixtures use 7 Oct 2026.
        page.clock.set_system_time(datetime.datetime(2026, 10, 7, 12, tzinfo=datetime.timezone.utc))
        page.on('pageerror', lambda e: errors.append(str(e)))
        page.on('console', lambda m: errors.append('console: ' + m.text) if m.type == 'error' else None)
        page.on('request', lambda r: requests.append(r.url) if r.url.startswith(('http:', 'https:')) else None)
        page.set_content(HTML); page.frame_locator('#visualFrame').locator('.ff-query').wait_for()
        size(w, h); run(f"ffTest.theme='{theme}';{js};ffTest.send()"); tick(220)
    def size(w, h):
        page.locator('#visualFrame').evaluate('(e,v)=>{e.style.width=v[0]+"px";e.style.height=v[1]+"px"}', [w, h])
        run(f'ffTest.width={w};ffTest.height={h};ffTest.send({{type:4,omitViews:true}})')
    def f(): return page.locator('#visualFrame').element_handle().content_frame()
    def u(s): return f().locator(s)
    def run(js): return f().evaluate(js)
    def tick(ms=80): page.wait_for_timeout(ms)
    def keys(): return run('ffTest.filter?.values||[]')
    def search(text): u('.ff-query').fill(text); u('.ff-query').press('Enter'); tick()
    def css(sel, prop): return u(sel).first.evaluate(f'e=>getComputedStyle(e).{prop}')
    def chip(name): return u(f'[data-ff-chip="{name}"]')
    def btn(name): return f().get_by_role('button', name=name, exact=True)
    def mode(): return u('.ff-row-options').first.get_attribute('data-ff-mode')
    def rgb(hexv): h = hexv.lstrip('#'); return f'rgb({int(h[0:2],16)}, {int(h[2:4],16)}, {int(h[4:6],16)})'
    def fmt():
        return run("""(()=>{const o={};for(const c of ffTest.visual.getFormattingModel().cards){const all=[...(c.topLevelToggle?[c.topLevelToggle]:[]),...c.groups.flatMap(g=>g.slices)];
          for(const s of all){const pr=s.control.properties;const items=pr.descriptor?[pr]:Object.values(pr).filter(x=>x&&x.descriptor);for(const x of items){const v=x.value;o[x.descriptor.objectName+'.'+x.descriptor.propertyName]=v&&typeof v==='object'&&'value' in v?v.value:v;if(x.options&&x.options.minValue)o[x.descriptor.objectName+'.'+x.descriptor.propertyName+'#range']=[x.options.minValue.value,x.options.maxValue.value];}}}return o;})()""")

    print('START layout and Mohamed\'s binding', flush=True)
    setup()
    check(f'Packaged release is {VERSION}', u('[data-ff-release]').get_attribute('data-ff-release') == VERSION)
    check('Actual code runs in an opaque sandbox frame', page.locator('#visualFrame').get_attribute('sandbox') == 'allow-scripts')
    check('A 76 px visual shows two rows: search, then options', u('[data-ff-layout]').get_attribute('data-ff-layout') == 'two-rows' and u('.ff-row-search').count() == 1 and u('.ff-row-options').count() == 1)
    check('Options row shows current values: Contains, All fields, Any field, Date', [x.strip() for x in u('.ff-row-options .ff-chip').all_inner_texts()] == ['Contains', 'All fields', 'Any field', 'Date'])
    page.locator('#visualFrame').screenshot(path=str(OUT / 'two-rows-idle.png'))
    run(MOHAMED); tick()
    check('Mohamed’s binding: HFB in Date fields does not block search', run('ffTest.visual.controller.canSearch') is True and run('ffTest.visual.hasError') is False)
    check('Mohamed’s binding: fields and dates are routed correctly', run('ffTest.visual.fields.map(f=>f.displayName)') == ['Article No', 'Article Name', 'HFB'] and run('ffTest.visual.dateFields.map(f=>f.displayName)') == ['RU EDS'])
    u('.ff-query').fill('vinterfint'); tick(650)
    check('Typing alone filters (search as you type is on by default)', keys() == [60637328, 60637329])
    check('Match count is shown', u('.ff-status').inner_text().strip() == '2 matches')
    check('HFB note is available but not shown as an error', u('.ff-info').count() == 1 and 'HFB' in u('.ff-info').get_attribute('title') and u('.ff-status-error').count() == 0)
    page.locator('#visualFrame').screenshot(path=str(OUT / 'mohamed-binding-vinterfint.png'))
    chip('date').click(); tick()
    check('RU EDS opens on the date with rows nearest today', u('.ff-step-input').input_value() in ('1 Oct 2026', '1 Dec 2026', '1 Jan 2027'))
    u('.ff-step-input').fill('1 Jan 2027'); btn('Apply').click(); tick()
    check('Text AND RU EDS date filter together', keys() == [60637328, 60637329] and 'RU EDS' in u('.ff-chip-active').inner_text())

    print('START typing safety and filter echo', flush=True)
    setup()
    u('.ff-query').fill('ST'); tick(450); u('.ff-query').press_sequentially('RALA'); tick(500)
    check('Two letters then more: live search keeps the draft', u('.ff-query').input_value() == 'STRALA' and keys() == [60637328, 60637329])
    u('.ff-query').evaluate('(e)=>e.setSelectionRange(2,2)'); run('ffTest.send()')
    check('Host data echo keeps the caret', u('.ff-query').evaluate('(e)=>e.selectionStart') == 2)
    check('Own echo (SemanticFilter + jsonFilters) is not a foreign filter', run('ffTest.visual.controller.needsRefresh') is False and u('.ff-status-error').count() == 0)
    n = run('ffTest.calls.length'); search('BILLY')
    check('A new search replaces the filter without clearing first', run(f'ffTest.calls.slice({n}).map(c=>c.filter===null)') == [False])
    run('ffTest.delay=600'); u('.ff-query').fill('BI'); tick(420); u('.ff-query').fill('BILLY'); tick(1200)
    check('Delayed host callbacks do not erase newer letters', u('.ff-query').input_value() == 'BILLY'); run('ffTest.delay=0')
    search('No such value'); check('No result: text kept, report empty, "No matches" shown', u('.ff-query').input_value() == 'No such value' and keys() == [] and u('.ff-status').inner_text().strip() == 'No matches')
    u('.ff-clear-text').click(); tick(); check('× clears only the text filter', run('ffTest.filter') is None and u('.ff-query').input_value() == '')

    print('START report theme', flush=True)
    for theme, accent, text, bg in [('default', '#118DFF', '#252423', '#FFFFFF'), ('green', '#1E5A44', '#1B2A24', '#FFFFFF'), ('dark', '#4CC2A0', '#F3F2F1', '#1F1F1F')]:
        setup(theme=theme)
        check(f'{theme} theme: search icon uses the first theme colour', css('.ff-search-btn', 'color') == rgb(accent))
        check(f'{theme} theme: text and background come from the theme', css('.ff-query', 'color') == rgb(text) and css('.ff-card', 'backgroundColor') == rgb(bg))
        page.locator('#visualFrame').screenshot(path=str(OUT / f'theme-{theme}.png'))
    setup(theme='green')
    check('Green theme: border uses the theme’s fourth-level colour', css('.ff-card', 'borderTopColor') == rgb('#A8B3AE'))
    model = fmt()
    check('Format pane shows theme colours for unset colours', model.get('barColors.accent') == '#1E5A44' and model.get('searchBar.background') == '#FFFFFF' and model.get('barText.color') == '#1B2A24' and model.get('barBorder.color') == '#A8B3AE')
    run("ffTest.theme='dark';ffTest.send({type:16,omitViews:true})"); tick()
    check('Switching the report theme re-colours the visual without new data', css('.ff-card', 'backgroundColor') == rgb('#1F1F1F') and css('.ff-search-btn', 'color') == rgb('#4CC2A0'))
    run("ffTest.theme='green';ffTest.metadata={barColors:{accent:{solid:{color:'#0058A3'}}}};ffTest.send()"); tick()
    check('A colour set in the Format pane wins over the theme', css('.ff-search-btn', 'color') == rgb('#0058A3') and fmt().get('barColors.accent') == '#0058A3')
    run("ffTest.metadata={};ffTest.send()"); tick()
    check('Reset to default returns to the theme colour', css('.ff-search-btn', 'color') == rgb('#1E5A44'))
    setup(theme='yellow'); u('.ff-query').focus()
    check('Light theme colour (yellow) is not used for icons on white', css('.ff-search-btn', 'color') == rgb('#252423'))
    check('Focus border stays visible with a yellow theme colour', css('.ff-card', 'borderTopColor') != rgb('#F2C811'))
    setup(js="ffTest.highContrast={foreground:'#FFFF00',background:'#000000',selected:'#00FFFF'}")
    check('High contrast uses only the host’s contrast colours', css('.ff-query', 'color') == rgb('#FFFF00') and css('.ff-card', 'backgroundColor') == rgb('#000000') and css('.ff-card', 'borderTopColor') == rgb('#FFFF00'))

    print('START Format pane options', flush=True)
    setup(); model = fmt()
    check('Format pane cards: Search, Reader options, Search bar, Border, Text, Colours', [c['displayName'] for c in run('ffTest.visual.getFormattingModel().cards')] == ['Search', 'Reader options', 'Search bar', 'Border', 'Text', 'Colours'])
    check('Default corner radius is 4 px (not very rounded)', model.get('searchBar.radius') == 4 and css('.ff-card', 'borderTopLeftRadius') == '4px')
    check('Search as you type is on by default in the Format pane', model.get('searchOptions.autoSearch') is True)
    check('Format pane limits match the visual', model.get('searchBar.barHeight#range') == [28, 52] and model.get('searchBar.radius#range') == [0, 24] and model.get('barBorder.width#range') == [1, 4] and model.get('barText.fontSize#range') == [8, 18])
    check('Border card has an on/off switch in its header', any(c.get('topLevelToggle') for c in run('ffTest.visual.getFormattingModel().cards') if c['displayName'] == 'Border'))
    for radius in [0, 8, 24]:
        run(f'ffTest.metadata={{searchBar:{{radius:{radius}}}}};ffTest.send()')
        check(f'Corner radius {radius} reaches the bar', css('.ff-card', 'borderTopLeftRadius') == f'{radius}px')
    run("ffTest.metadata={barBorder:{show:false}};ffTest.send()"); check('Border can be switched off', css('.ff-card', 'borderTopWidth') == '0px')
    run("ffTest.metadata={barBorder:{width:3,color:{solid:{color:'#0058A3'}}}};ffTest.send()"); tick(200)  # border colour has a 0.12 s transition
    check('Border width and colour', css('.ff-card', 'borderTopWidth') == '3px' and css('.ff-card', 'borderTopColor') == rgb('#0058A3'))
    run("ffTest.metadata={barText:{fontFamily:'Georgia, serif',fontSize:12,color:{solid:{color:'#5A2D82'}}}};ffTest.send()")
    check('Font, text size (pt) and text colour', 'Georgia' in css('.ff-query', 'fontFamily') and css('.ff-query', 'fontSize') == '16px' and css('.ff-query', 'color') == rgb('#5A2D82'))
    run("ffTest.metadata={searchBar:{shadow:true,background:{solid:{color:'#F7F3E8'}}}};ffTest.send()"); check('Shadow and background colour', css('.ff-card', 'boxShadow') != 'none' and css('.ff-card', 'backgroundColor') == rgb('#F7F3E8'))
    run("ffTest.metadata={searchOptions:{placeholder:'Zoek artikel of leverancier'}};ffTest.send()"); check('Custom placeholder text', u('.ff-query').get_attribute('placeholder') == 'Zoek artikel of leverancier')
    run("ffTest.metadata={searchOptions:{showFieldNames:true}};ffTest.send()"); check('Field names in placeholder', u('.ff-query').get_attribute('placeholder') == 'Search Article Name, Supplier…')
    run("ffTest.metadata={optionsRow:{showMatch:false,showLogic:false,showCount:false}};ffTest.send()"); search('BILLY')
    check('Creator can hide options (match type, any/every) and the count', [x.strip() for x in u('.ff-row-options .ff-chip').all_inner_texts()] == ['All fields', 'Date'] and u('.ff-status').count() == 0)
    run("ffTest.metadata={optionsRow:{layout:'oneRow'}};ffTest.send()"); check('Creator can keep options behind a button even in a tall visual', u('[data-ff-layout]').get_attribute('data-ff-layout') == 'one-row' and u('.ff-options-btn').count() == 1)
    run("ffTest.metadata={optionsRow:{layout:'off'}};ffTest.send()"); check('Creator can hide reader options completely', u('.ff-options-btn').count() == 0 and u('.ff-row-options').count() == 0)
    run("ffTest.metadata={searchOptions:{autoSearch:false}};ffTest.send()"); u('.ff-clear-text').click(); tick(); u('.ff-query').fill('STRALA'); tick(600)
    check('With search as you type off, typing waits for Enter', run('ffTest.filter') is None); u('.ff-query').press('Enter'); tick(); check('Enter applies', keys() == [60637328, 60637329])
    check('Reader actions never write report formatting', run('ffTest.persistCalls') == 0)

    print('START options row', flush=True)
    setup(); search('BILLY')
    chip('match').click(); tick(); check('Match chip opens its choices in the same row', mode() == 'match' and u('.ff-choice[aria-pressed=true]').inner_text().strip() == 'Contains')
    page.locator('#visualFrame').screenshot(path=str(OUT / 'match-choices.png'))
    btn('Exact').click(); tick(); check('Choosing Exact applies at once and returns', mode() == 'summary' and keys() == [60637334] and 'ff-changed' in chip('match').get_attribute('class'))
    chip('match').click(); btn('Contains').click(); tick()
    chip('fields').click(); tick(); check('Fields open as checkboxes', u('.ff-toggle').count() == 2)
    page.locator('#visualFrame').screenshot(path=str(OUT / 'fields-choices.png'))
    f().get_by_role('button', name='Supplier').click(); tick()
    check('Unticking Supplier applies at once', keys() == [60637329, 60637331, 60637334])
    check('The last ticked field cannot be removed', f().get_by_role('button', name='Article Name').is_disabled())
    btn('Select all').click(); tick(); check('Select all restores every field', keys() == [60637329, 60637330, 60637331, 60637334])
    u('.ff-back').first.click(); tick()
    chip('logic').click(); btn('Every selected field').click(); tick(); check('Every field (AND) means the phrase in each field of one row', keys() == [60637334])
    chip('logic').click(); btn('Any selected field').click(); tick()
    chip('more').click(); tick(); page.locator('#visualFrame').screenshot(path=str(OUT / 'more-options.png'))
    f().get_by_role('switch', name='Ignore accents').click(); tick(); search('STRALA')
    check('Accents switch off: STRALA no longer matches STRÅLA', keys() == [])
    check('The More strip stays open so both switches can be changed', mode() == 'more')
    f().get_by_role('switch', name='Ignore accents').click(); tick(); search('STRALA'); check('Accents back on', keys() == [60637328, 60637329])
    u('.ff-row-options .ff-back').click(); tick()
    chip('match').click(); btn('Exact').click(); tick(); chip('more').click(); btn('Reset options').click(); tick()
    check('Reset options returns to the creator defaults', run('ffTest.visual.options.mode') == 'contains' and mode() == 'summary')
    chip('match').click(); tick(); u('.ff-row-options').press('Escape'); tick(); check('Esc goes back and focus returns to the chip', mode() == 'summary' and chip('match').evaluate('e=>e===document.activeElement'))

    print('START dates', flush=True)
    setup()
    chip('date').click(); tick()
    check('Date editor opens in the options row with focus in the date field', mode() == 'date' and u('.ff-step-input').evaluate('e=>e===document.activeElement'))
    check('Date field opens on the date with rows nearest today', u('.ff-step-input').input_value() == '8 Oct 2026')
    page.locator('#visualFrame').screenshot(path=str(OUT / 'date-editor.png'))
    btn('Apply').click(); tick(); check('On a date covers the whole calendar day', keys() == [60637328, 60637329])
    check('Chip names the column and the day', u('.ff-chip-active').inner_text().replace('\n', ' ').split() == ['Delivery', 'Date', '·', '8', 'Oct', '2026'])
    chip('date').click(); f().get_by_role('button', name='Next date with rows').click(); tick()
    check('› steps to the next date that has rows', u('.ff-step-input').input_value() == '12 Oct 2026')
    u('.ff-step-input').press('ArrowUp'); check('Arrow up steps back', u('.ff-step-input').input_value() == '8 Oct 2026')
    u('.ff-step-input').fill('09/10/2026'); tick(); u('.ff-step-input').press('Enter'); tick()
    check('A day without rows cannot be applied for "On a date"', btn('Apply').is_disabled() and 'No rows on 9 Oct 2026' in u('.ff-field-error').inner_text() and keys() == [60637328, 60637329])
    u('.ff-step-input').fill('12 okt 2026'); u('.ff-step-input').press('Enter'); tick(); check('Typed Dutch date with Enter applies', keys() == [60637330])
    chip('date').click(); chip('dateCondition').click(); tick(); check('Condition opens as choices', mode() == 'dateCondition')
    btn('Between').click(); tick(); f().get_by_role('textbox', name='From').fill('01/10/2026'); f().get_by_role('textbox', name='To').fill('31/10/2026')
    page.locator('#visualFrame').screenshot(path=str(OUT / 'date-between.png'))
    btn('Apply').click(); tick(); check('Between includes both whole end days', keys() == [60637328, 60637329, 60637330, 60637332])
    check('Range chip reads 1–31 Oct', '1–31 Oct' in u('.ff-chip-active').inner_text() if datetime.date.today().year == 2026 else '1–31 Oct 2026' in u('.ff-chip-active').inner_text())
    chip('date').click(); f().get_by_role('textbox', name='From').fill('31/10/2026'); f().get_by_role('textbox', name='To').fill('01/10/2026'); tick()
    check('Reversed range cannot be applied', btn('Apply').is_disabled() and keys() == [60637328, 60637329, 60637330, 60637332]); u('.ff-row-options').press('Escape')
    for cond, day, expected in [('On or before', '08/10/2026', [60637328, 60637329, 60637334]), ('On or after', '31/10/2026', [60637332, 60637333]), ('No date', None, [60637331])]:
        chip('date').click(); chip('dateCondition').click(); btn(cond).click(); tick()
        if day: u('.ff-step-input').fill(day)
        btn('Apply').click(); tick(); check(f'{cond} is inclusive / exact', keys() == expected)
    search('BILLY'); check('Text AND date together', keys() == [60637331])
    u('.ff-chip-x').click(); tick(); check('Date × clears only the date', keys() == [60637329, 60637330, 60637331, 60637334] and u('.ff-query').input_value() == 'BILLY')
    chip('date').click(); btn('Apply').click(); tick(); chip('more').click(); btn('Clear all').click(); tick()
    check('Clear all clears text and date, keeps preferences', run('ffTest.filter') is None and u('.ff-query').input_value() == '' and u('.ff-chip-active').count() == 0)
    setup(js="""(()=>{const c=(name,roles,type)=>({displayName:name,queryName:'Articles.'+name,expr:{source:{entity:'Articles'},ref:name},roles,type});
      ffTest.customColumns=[c('Article No',{recordKey:true},{numeric:true}),c('Article Name',{fields:true},{text:true}),c('RU SSD',{dates:true},{dateTime:true}),c('RU EDS',{dates:true},{dateTime:true})];
      ffTest.rawRows=[[1,'STRÅLA',new Date(2026,9,1),new Date(2027,0,1)],[2,'BILLY',new Date(2026,9,8),new Date(2027,0,1)]];})()""")
    chip('date').click(); tick(); check('With several date columns the column is a choice', chip('dateColumn').count() == 1)
    chip('dateColumn').click(); btn('RU EDS').click(); tick(); check('Choosing RU EDS re-anchors the date to one with rows', u('.ff-step-input').input_value() == '1 Jan 2027')
    btn('Apply').click(); tick(); check('RU EDS filter applied', keys() == [1, 2] and 'RU EDS' in u('.ff-chip-active').inner_text())

    print('START one-row layout (short visual)', flush=True)
    setup(h=40); search('STRALA')
    check('A 40 px visual shows one row with date and options buttons', u('[data-ff-layout]').get_attribute('data-ff-layout') == 'one-row' and u('.ff-date-btn').count() == 1 and u('.ff-options-btn').count() == 1)
    check('Count shown in words, not a bare number', u('.ff-count').inner_text().strip() == '2 matches')
    page.locator('#visualFrame').screenshot(path=str(OUT / 'one-row.png'))
    u('.ff-options-btn').click(); tick(); check('Options button turns the row into the options row', mode() == 'summary' and u('.ff-query').count() == 0)
    page.locator('#visualFrame').screenshot(path=str(OUT / 'one-row-options.png'))
    chip('match').click(); btn('Exact').click(); tick(); f().get_by_role('button', name='Back to search').click(); tick()
    check('Back to search keeps the text and the new match type', u('.ff-query').input_value() == 'STRALA' and keys() == [] and run('ffTest.visual.options.mode') == 'exact')
    u('.ff-options-btn').click(); chip('match').click(); btn('Contains').click(); f().get_by_role('button', name='Back to search').click(); tick()
    u('.ff-date-btn').click(); tick(); check('Date button opens the date editor in the row', mode() == 'date')
    btn('Apply').click(); tick(); f().get_by_role('button', name='Back to search').click(); tick()
    check('Date chip appears in the single row', u('.ff-row-search .ff-chip-active').count() == 1 and keys() == [60637328, 60637329])
    page.locator('#visualFrame').screenshot(path=str(OUT / 'one-row-date.png'))
    for w, h in [(180, 28), (240, 32), (320, 40), (600, 40), (600, 76), (360, 76), (900, 44)]:
        setup(w, h); search('BILLY')
        check(f'Fits {w}×{h} without spilling out', u('.ff-card').evaluate('e=>e.scrollWidth<=e.clientWidth+1') and u('.ff-root').evaluate('e=>e.scrollHeight<=e.clientHeight+1'))

    print('START status, errors and host policy', flush=True)
    setup(); search('STRALA'); run('ffTest.failApply=true'); search('BILLY')
    check('Failed apply keeps older filter and the newer text', keys() == [60637328, 60637329] and u('.ff-query').input_value() == 'BILLY')
    check('The reason is visible in the options row', 'Test host rejected filter' in u('.ff-status-error').inner_text())
    u('.ff-status-error').click(); tick(); check('Clicking the problem shows the full message', mode() == 'notice' and 'Test host rejected filter' in u('.ff-notice').inner_text())
    run('ffTest.failApply=false;ffTest.failClear=true'); u('.ff-clear-text').click(); tick()
    check('Failed clear keeps the draft and previous filter', u('.ff-query').input_value() == 'BILLY' and keys() == [60637328, 60637329])
    setup(js="""ffTest.customColumns=[{displayName:'Article Name',queryName:'Articles.Article Name',expr:{source:{entity:'Articles'},ref:'Article Name'},roles:{fields:true},type:{text:true}}];ffTest.rawRows=[['STRALA']]""")
    search('STRALA'); check('Missing key: no wrong filter, reason shown, text kept', run('ffTest.calls.length') == 0 and 'Record key' in u('.ff-status-error').get_attribute('title') and u('.ff-query').input_value() == 'STRALA')
    setup(js="ffTest.customColumns=[];ffTest.rawRows=[];ffTest.search=[];ffTest.dateFields=[]")
    run('ffTest.visual.update({type:2,viewport:{width:600,height:76},dataViews:[{metadata:{columns:[],objects:{}}}]})'); tick()
    check('Nothing bound: the placeholder says what to add', 'Record key' in u('.ff-query').get_attribute('placeholder'))
